using System.Text;using EventLensAI.Application.Services;
namespace EventLensAI.Infrastructure.Storage;
internal sealed class BasicFileScanner:IFileScanner{public async Task<FileScanResult>ScanAsync(Stream content,string fileName,CancellationToken ct){if(!content.CanSeek)return new(false,"BasicSignatureScanner","Stream is not seekable.");var buffer=new byte[Math.Min(content.Length,8192)];var read=await content.ReadAsync(buffer,ct);content.Position=0;var text=Encoding.ASCII.GetString(buffer,0,read);if(text.Contains("EICAR-STANDARD-ANTIVIRUS-TEST-FILE",StringComparison.Ordinal))return new(false,"BasicSignatureScanner","Known malware test signature detected.");var ext=Path.GetExtension(fileName).ToLowerInvariant();if(ext is ".exe" or ".dll" or ".bat" or ".cmd" or ".ps1" or ".js" or ".vbs" or ".msi")return new(false,"BasicSignatureScanner","Executable content is not permitted.");return new(true,"BasicSignatureScanner",null);}}
